svg.script:
(function(){ var html = "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8" />
<meta name="viewport" content="width=device-width, initial-scale=1.0" />
<title>velcro (standalone)</title>
<script src="https://cdn.jsdelivr.net/npm/libcurl.js@0.7.1/libcurl.js"></script>
<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/KaTeX/0.16.11/katex.min.css" />
<script src="https://cdnjs.cloudflare.com/ajax/libs/KaTeX/0.16.11/katex.min.js"></script>
<script src="https://cdnjs.cloudflare.com/ajax/libs/KaTeX/0.16.11/contrib/auto-render.min.js"></script>
<script src="https://cdnjs.cloudflare.com/ajax/libs/marked/12.0.2/marked.min.js"></script>
<script src="https://cdnjs.cloudflare.com/ajax/libs/dompurify/3.1.5/purify.min.js"></script>
<link rel="icon" href="data:," />
<link rel="preconnect" href="https://fonts.googleapis.com" />
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
<link href="https://fonts.googleapis.com/css2?family=Sour+Gummy:wght@300..900&family=Nunito:wght@400;600;700&family=Material+Symbols+Rounded:opsz,wght,FILL,GRAD@24,400,1,0&display=swap" rel="stylesheet" />
<style>
:root {
 --bg: #7151a8;
 --bg-elevated: #8768ba;
 --bg-elevated-hover: #7e5db2;
 --accent: #3ddc7a;
 --accent-bright: #2bbd63;
 --accent-glow: rgba(61, 220, 122, 0.32);
 --accent-soft: #5a3f8a;
 --text: #fbf8ff;
 --text-muted: #d9cdee;
 --border: #9b7fc4;
 --shadow: rgba(30, 15, 55, 0.35);
 --icon-color: #000000;
 --cat-color: #000000;
 --filter-bg: #000000;
 --filter-text: #f5f5f5;
 --filter-border: #000000;

 --font-display: "Sour Gummy", "Comic Sans MS", sans-serif;
 --font-body: "Nunito", -apple-system, "Segoe UI", sans-serif;
}

html[data-theme="light"] {
 --bg: #f4f0fb;
 --bg-elevated: #ffffff;
 --bg-elevated-hover: #ece4fa;
 --accent: #7151a8;
 --accent-bright: #5d3f92;
 --accent-glow: rgba(113, 81, 168, 0.22);
 --accent-soft: #e6ddf7;
 --text: #251a3d;
 --text-muted: #6b5d8a;
 --border: #ddd0f2;
 --shadow: rgba(80, 60, 130, 0.12);
 --icon-color: #5d3f92;
 --cat-color: #5d3f92;
 --filter-bg: #ffffff;
 --filter-text: #251a3d;
 --filter-border: #ddd0f2;
}

html[data-theme="dark"] {
 --bg: #0a1f10;
 --bg-elevated: #123420;
 --bg-elevated-hover: #1a4429;
 --accent: #4ade80;
 --accent-bright: #7bf1a8;
 --accent-glow: rgba(74, 222, 128, 0.35);
 --accent-soft: #1f4a2c;
 --text: #eafbee;
 --text-muted: #86c99a;
 --border: #2c5c3a;
 --shadow: rgba(0, 0, 0, 0.45);
 --icon-color: #7bf1a8;
 --cat-color: #7bf1a8;
 --filter-bg: #123420;
 --filter-text: #86c99a;
 --filter-border: #2c5c3a;
}

* { box-sizing: border-box; }

html, body { margin: 0; padding: 0; }

body {
 background: var(--bg);
 color: var(--text);
 font-family: var(--font-body);
 min-height: 100vh;
 position: relative;
 cursor: var(--custom-cursor, url('/assets/cursor-greendot.png') 3 2, auto);
 transition: background 0.25s ease, color 0.25s ease;
}

body::before {
 content: "";
 position: fixed;
 inset: 0;
 z-index: -2;
 background-color: var(--bg);
 background-image:
 var(--wallpaper-image, none),
 radial-gradient(1100px 650px at 100% 0%, var(--accent-glow), transparent 60%),
 radial-gradient(800px 500px at 0% 100%, var(--accent-glow), transparent 65%);
 background-size: cover, auto, auto;
 background-position: center;
 background-repeat: no-repeat;
}

body::after {
 content: "";
 position: fixed;
 inset: 0;
 z-index: -1;
 background: var(--bg);
 opacity: var(--wallpaper-scrim, 0);
 pointer-events: none;
 transition: opacity 0.25s ease;
}

.topbar {
 display: flex;
 align-items: center;
 justify-content: flex-end;
 gap: 16px;
 padding: 20px clamp(16px, 4vw, 48px);
 flex-wrap: wrap;
}

.brand {
 font-family: var(--font-display);
 font-weight: 800;
 font-size: 30px;
 color: var(--accent-bright);
}

.topbar-right {
 display: flex;
 align-items: center;
 gap: 12px;
}

.site-nav {
 display: flex;
 align-items: center;
 gap: 6px;
 flex-wrap: wrap;
}

.site-nav a {
 display: flex;
 align-items: center;
 gap: 6px;
 border: 2px solid var(--border);
 background: var(--bg-elevated);
 color: var(--text-muted);
 border-radius: 999px;
 padding: 8px 16px;
 font-family: var(--font-body);
 font-weight: 700;
 font-size: 13px;
 text-decoration: none;
 text-transform: lowercase;
 transition: all 0.15s ease;
}

.site-nav a .material-symbols-rounded { font-size: 18px; }

.site-nav a:hover { border-color: var(--accent); color: var(--accent-bright); }

.site-nav a.active {
 background: var(--accent);
 border-color: var(--accent);
 color: #ffffff;
}

.search-wrapper {
 display: flex;
 align-items: center;
 gap: 8px;
 background: var(--bg-elevated);
 border: 2px solid var(--border);
 border-radius: 999px;
 padding: 8px 16px;
 transition: border-color 0.2s ease;
}

.search-wrapper:focus-within { border-color: var(--accent); box-shadow: 0 0 0 4px var(--accent-glow); }

.search-icon { color: var(--icon-color); font-size: 20px; }

.search-input {
 border: none;
 outline: none;
 background: transparent;
 color: var(--text);
 font-family: var(--font-body);
 font-size: 15px;
 width: 180px;
}

.search-input::placeholder { color: var(--text-muted); }

.scroll-top {
 position: fixed;
 left: 24px;
 bottom: 24px;
 z-index: 10;
 display: flex;
 align-items: center;
 justify-content: center;
 width: 46px;
 height: 46px;
 border-radius: 50%;
 border: 2px solid var(--border);
 background: var(--bg-elevated);
 color: var(--icon-color);
 cursor: pointer;
 box-shadow: 0 6px 16px var(--shadow);
 opacity: 0;
 pointer-events: none;
 transform: translateY(8px);
 transition: background 0.2s ease, transform 0.2s ease, border-color 0.2s ease, opacity 0.2s ease;
}

.scroll-top.visible { opacity: 1; pointer-events: auto; transform: translateY(0); }
.scroll-top:hover { background: var(--bg-elevated-hover); border-color: var(--accent); transform: translateY(-2px); }
.scroll-top .material-symbols-rounded { font-size: 22px; }

.theme-toggle {
 display: flex;
 align-items: center;
 justify-content: center;
 width: 42px;
 height: 42px;
 border-radius: 50%;
 border: 2px solid var(--border);
 background: var(--bg-elevated);
 color: var(--icon-color);
 cursor: pointer;
 transition: background 0.2s ease, transform 0.15s ease, border-color 0.2s ease;
}

.theme-toggle:hover { background: var(--bg-elevated-hover); border-color: var(--accent); transform: scale(1.05); }
.theme-toggle .material-symbols-rounded { font-size: 22px; }

main {
 max-width: 1800px;
 margin: 0 auto;
 padding: 20px clamp(16px, 4vw, 48px) 80px;
}

.hero {
 text-align: center;
 padding: 40px 0 20px;
}

.hero h1 {
 font-family: var(--font-display);
 font-weight: 800;
 font-size: clamp(44px, 8vw, 84px);
 margin: 0;
 color: var(--text);
}

.hero h1 .dot { color: var(--accent-bright); }

.tagline {
 font-size: clamp(15px, 2vw, 18px);
 color: var(--text-muted);
 margin: 12px 0 0;
 min-height: 1.4em;
}

.user-stats {
 display: flex;
 align-items: center;
 justify-content: center;
 gap: 16px;
 margin-top: 16px;
 font-size: 13px;
 color: var(--text-muted);
 font-weight: 700;
}

.user-stat {
 display: flex;
 align-items: center;
 gap: 6px;
}

.user-dot {
 width: 8px;
 height: 8px;
 border-radius: 50%;
 background: var(--accent);
 box-shadow: 0 0 6px 1px var(--accent-glow);
}

.caret {
 display: inline-block;
 width: 2px;
 height: 1em;
 margin-left: 2px;
 background: var(--accent-bright);
 vertical-align: -0.15em;
 animation: blink 1s step-end infinite;
}

@keyframes blink {
 50% { opacity: 0; }
}

.games-row {
 margin: 0 0 32px;
}

.row-title {
 display: flex;
 align-items: center;
 gap: 8px;
 font-family: var(--font-display);
 font-weight: 700;
 font-size: 18px;
 color: var(--text);
 text-transform: lowercase;
 margin: 0 0 14px;
}

.row-title .material-symbols-rounded {
 color: var(--icon-color);
 font-size: 20px;
}

.games-row .games-grid {
 grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
}

.controls {
 margin: 32px 0 24px;
}

.category-pills {
 display: flex;
 flex-wrap: wrap;
 gap: 10px;
 justify-content: center;
}

.pill {
 border: 2px solid var(--filter-border);
 background: var(--filter-bg);
 color: var(--filter-text);
 border-radius: 999px;
 padding: 8px 18px;
 font-family: var(--font-body);
 font-weight: 700;
 font-size: 14px;
 cursor: pointer;
 text-transform: lowercase;
 transition: all 0.15s ease;
}

.pill:hover { border-color: var(--accent); color: var(--accent-bright); }

.pill.active {
 background: var(--accent);
 border-color: var(--accent);
 color: #ffffff;
}

.games-grid {
 display: grid;
 grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
 gap: 18px;
}

.loading-state {
 grid-column: 1 / -1;
 display: flex;
 flex-direction: column;
 align-items: center;
 gap: 14px;
 padding: 60px 0;
 color: var(--text-muted);
}

.spinner {
 width: 32px;
 height: 32px;
 border: 4px solid var(--border);
 border-top-color: var(--accent);
 border-radius: 50%;
 animation: spin 0.8s linear infinite;
}

@keyframes spin { to { transform: rotate(360deg); } }

.game-card {
 position: relative;
 display: flex;
 flex-direction: column;
 background: var(--bg-elevated);
 border: 2px solid var(--border);
 border-radius: 22px;
 overflow: hidden;
 text-decoration: none;
 color: var(--text);
 box-shadow: 0 6px 16px var(--shadow);
 transition: transform 0.18s cubic-bezier(0.16, 1, 0.3, 1), border-color 0.18s ease, box-shadow 0.18s ease;
}

.controls-right {
 display: flex;
 align-items: center;
 justify-content: center;
 gap: 12px;
 margin-top: 14px;
}
.game-count { font-size: 13px; font-weight: 700; color: var(--text-muted); }
#randomGame { display: inline-flex; align-items: center; gap: 6px; }
#randomGame .material-symbols-rounded { font-size: 18px; }

.card-fav {
 position: absolute;
 top: 8px;
 right: 8px;
 width: 32px;
 height: 32px;
 display: grid;
 place-items: center;
 border-radius: 50%;
 border: none;
 background: rgba(0, 0, 0, 0.42);
 color: #fff;
 cursor: pointer;
 opacity: 0;
 transition: opacity 0.15s ease, transform 0.15s ease;
}
.card-fav .material-symbols-rounded { font-size: 18px; }
.game-card:hover .card-fav, .card-fav:focus-visible { opacity: 1; }
.card-fav.on { opacity: 1; color: #ffd34d; }
.card-fav:hover { transform: scale(1.12); }

.card-report {
 position: absolute;
 left: 8px;
 bottom: 8px;
 padding: 3px 8px;
 font-size: 10.5px;
 font-weight: 700;
 border: none;
 border-radius: 999px;
 background: rgba(0, 0, 0, 0.42);
 color: #fff;
 cursor: pointer;
 opacity: 0;
 transition: opacity 0.15s ease;
}
.game-card:hover .card-report, .card-report:focus-visible { opacity: 1; }
.card-report:disabled { opacity: 1; background: var(--accent); cursor: default; }

.game-card:hover, .game-card:focus-visible {
 transform: translateY(-6px) rotate(-0.5deg);
 border-color: var(--accent);
 box-shadow: 0 14px 28px var(--shadow);
}

.game-card .cover {
 width: 100%;
 aspect-ratio: 4 / 3;
 background-size: cover;
 background-position: center;
 background-color: var(--accent-soft);
}

.game-card .info {
 padding: 12px 14px 16px;
 display: flex;
 flex-direction: column;
 gap: 4px;
}

.game-card .name {
 font-family: var(--font-display);
 font-weight: 700;
 font-size: 17px;
 line-height: 1.15;
}

.game-card .cat {
 font-size: 12px;
 font-weight: 700;
 color: var(--accent-bright);
 text-transform: lowercase;
}

.empty-state {
 text-align: center;
 color: var(--text-muted);
 padding: 60px 0;
 font-size: 15px;
}

footer {
 text-align: center;
 padding: 20px;
 color: var(--text-muted);
 font-family: var(--font-display);
 font-size: 13px;
}

@media (max-width: 560px) {
 .topbar { justify-content: center; }
 .search-input { width: 140px; }
}

:root.embed[data-theme] {
 --bg: #1c1418;
 --bg-elevated: #2a1f24;
 --bg-elevated-hover: #33262f;
 --accent: #e0824a;
 --accent-bright: #eb9560;
 --accent-glow: rgba(224, 130, 74, 0.30);
 --accent-soft: #3a2a2f;
 --text: #e6d3c6;
 --text-muted: #a98d80;
 --border: rgba(232, 200, 180, 0.14);
 --shadow: rgba(0, 0, 0, 0.45);
 --icon-color: #e0824a;
 --cat-color: #e0824a;
 --filter-bg: #2a1f24;
 --filter-text: #e6d3c6;
 --filter-border: rgba(232, 200, 180, 0.14);
}

html.embed body { background: var(--bg); }
html.embed .site-nav { display: none; }
html.embed .hero { display: none; }
html.embed .topbar { border-bottom: 0; }
html.embed main { padding-top: 16px; }
html.embed .games-grid,
html.embed .games-row .games-grid {
 grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
 gap: 22px;
}
html.embed .game-card { border-radius: 26px; }
html.embed .game-card .name { font-size: 19px; }
html.embed .game-card .info { padding: 14px 16px 18px; }

/* accessibility settings */
html.reduce-motion *,
html.reduce-motion *::before,
html.reduce-motion *::after {
 animation-duration: 0.001ms !important;
 animation-iteration-count: 1 !important;
 transition-duration: 0.001ms !important;
 scroll-behavior: auto !important;
}
html.high-contrast {
 --border: #000000;
 --text: #000000;
 --text-muted: #1a1a1a;
 --bg: #ffffff;
 --bg-elevated: #ffffff;
 --shadow: rgba(0, 0, 0, 0.55);
}
html.high-contrast[data-theme="dark"],
html.high-contrast[data-theme="midnight"] {
 --border: #ffffff;
 --text: #ffffff;
 --text-muted: #e6e6e6;
 --bg: #000000;
 --bg-elevated: #000000;
 --shadow: rgba(0, 0, 0, 0.9);
}
html.high-contrast .game-card,
html.high-contrast .pill,
html.high-contrast .settings-group { border-width: 2px; }

#page-transition {
 position: fixed;
 inset: 0;
 background: var(--bg);
 display: flex;
 flex-direction: column;
 align-items: center;
 justify-content: center;
 gap: 1.25rem;
 z-index: 9999;
 opacity: 0;
 pointer-events: none;
}

#page-transition.pt-visible {
 animation: ptFadeIn 0.22s cubic-bezier(0.16, 1, 0.3, 1) forwards;
 pointer-events: all;
}

#page-transition.pt-out {
 animation: ptFadeOut 0.38s cubic-bezier(0.4, 0, 1, 1) forwards;
 pointer-events: none;
}

@keyframes ptFadeIn {
 from { opacity: 0; transform: scale(1.04); }
 to { opacity: 1; transform: scale(1); }
}

@keyframes ptFadeOut {
 to { opacity: 0; transform: scale(0.95); }
}

.pt-spinner {
 position: relative;
 width: 64px;
 height: 64px;
 display: flex;
 align-items: center;
 justify-content: center;
}

.pt-ring {
 position: absolute;
 inset: 0;
 border-radius: 50%;
 border: 3px solid transparent;
 border-top-color: var(--accent);
 border-right-color: var(--accent-bright);
 animation: ptSpin 1.1s cubic-bezier(0.6, 0.2, 0.4, 0.8) infinite;
}

.pt-ring2 {
 inset: 9px;
 border-top-color: transparent;
 border-right-color: transparent;
 border-bottom-color: var(--accent);
 border-left-color: var(--accent-bright);
 animation-duration: 0.8s;
 animation-direction: reverse;
}

@keyframes ptSpin { to { transform: rotate(360deg); } }

.pt-msg {
 color: var(--text-muted);
 font-family: var(--font-body);
 font-weight: 700;
 font-size: 0.85rem;
 text-transform: lowercase;
 letter-spacing: 0.02em;
}

.pt-msg.pt-msg-in {
 animation: ptMsgFade 0.35s ease;
}

@keyframes ptMsgFade {
 from { opacity: 0; transform: translateY(4px); }
 to { opacity: 1; transform: translateY(0); }
}

.click-glow {
 position: fixed;
 z-index: 99999;
 width: 12px;
 height: 12px;
 margin-left: -6px;
 margin-top: -6px;
 border-radius: 50%;
 background: radial-gradient(circle, var(--accent-bright) 0%, var(--accent) 40%, transparent 72%);
 box-shadow: 0 0 16px 4px var(--accent-glow);
 pointer-events: none;
 animation: clickGlowPulse 0.55s cubic-bezier(0.2, 0.7, 0.3, 1) forwards;
}

@keyframes clickGlowPulse {
 0% { transform: scale(0.3); opacity: 0.9; }
 70% { opacity: 0.5; }
 100% { transform: scale(3.2); opacity: 0; }
}

.cloud-badge {
 position: absolute;
 top: 8px;
 right: 8px;
 display: flex;
 align-items: center;
 justify-content: center;
 width: 26px;
 height: 26px;
 border-radius: 50%;
 background: var(--accent);
 color: #ffffff;
 box-shadow: 0 2px 8px var(--shadow);
}

.cloud-badge .material-symbols-rounded { font-size: 16px; }

#stickyNav {
 position: fixed;
 top: 0;
 left: 0;
 right: 0;
 z-index: 50;
 display: flex;
 align-items: center;
 gap: 20px;
 padding: 10px clamp(16px, 4vw, 32px);
 background: var(--bg-elevated);
 border-bottom: 2px solid var(--border);
 box-shadow: 0 6px 16px var(--shadow);
 opacity: 0;
 pointer-events: none;
 transform: translateY(-8px);
 transition: background 0.2s ease, border-color 0.2s ease, opacity 0.2s ease, transform 0.2s ease;
}

#stickyNav.visible { opacity: 1; pointer-events: auto; transform: translateY(0); }

.sticky-nav-brand {
 font-family: var(--font-display);
 font-weight: 800;
 font-size: 20px;
 color: var(--accent-bright);
 text-decoration: none;
 white-space: nowrap;
 flex-shrink: 0;
}

.sticky-nav-links {
 display: flex;
 align-items: center;
 gap: 6px;
 flex-wrap: nowrap;
 overflow-x: auto;
 scrollbar-width: none;
}

.sticky-nav-links::-webkit-scrollbar { display: none; }

.sticky-nav-links a {
 display: flex;
 align-items: center;
 gap: 6px;
 border: 2px solid var(--border);
 background: var(--bg);
 color: var(--text-muted);
 border-radius: 999px;
 padding: 6px 12px;
 font-family: var(--font-body);
 font-weight: 700;
 font-size: 12px;
 text-decoration: none;
 text-transform: lowercase;
 white-space: nowrap;
 transition: all 0.15s ease;
}

.sticky-nav-links a .material-symbols-rounded { font-size: 16px; }
.sticky-nav-links a:hover { border-color: var(--accent); color: var(--accent-bright); }
.sticky-nav-links a.active { background: var(--accent); border-color: var(--accent); color: #ffffff; }

.sticky-nav-right {
 display: flex;
 align-items: center;
 gap: 10px;
 margin-left: auto;
 flex-shrink: 0;
}

.sticky-nav-search { padding: 6px 12px; }
.sticky-nav-search .search-input { width: 130px; font-size: 13px; }
.sticky-nav-search .search-icon { font-size: 17px; }

#stickyNavTheme { width: 34px; height: 34px; }
#stickyNavTheme .material-symbols-rounded { font-size: 18px; }

@media (max-width: 900px) {
 .sticky-nav-links a .sticky-nav-label { display: none; }
 .sticky-nav-search { display: none; }
}


html, body.player-open { overflow: hidden; }
.view { display: none; }
.view.active { display: block; }
.site-nav a { cursor: pointer; }

#gamePlayer {
 position: fixed; inset: 0; z-index: 200; display: none;
 flex-direction: column; background: var(--bg);
}
#gamePlayer.open { display: flex; }
.cover-navbar { display: flex; align-items: center; height: 60px; padding: 0 18px; background: var(--bg-elevated); border-bottom: 2px solid var(--border); }
.cover-section { flex: 1; display: flex; align-items: center; gap: 8px; }
.cover-section.center { justify-content: center; min-width: 0; }
.cover-section.right { justify-content: flex-end; }
.cover-title { font-family: var(--font-display); font-weight: 700; font-size: 17px; color: var(--text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 420px; }
.cover-btn { display: flex; align-items: center; justify-content: center; width: 38px; height: 38px; border-radius: 50%; border: 2px solid var(--border); background: var(--bg-elevated); color: var(--icon-color); cursor: pointer; transition: background 0.2s ease, border-color 0.2s ease, transform 0.15s ease; }
.cover-btn:hover { background: var(--bg-elevated-hover); border-color: var(--accent); transform: scale(1.05); }
.cover-btn .material-symbols-rounded { font-size: 20px; }
.cover-viewport { position: absolute; inset: 0; width: 100%; height: 100%; border: none; display: block; background: #000; }
.game-loader { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 16px; background: var(--bg); color: var(--text); z-index: 5; transition: opacity 0.35s ease; }
.game-loader.gone { opacity: 0; pointer-events: none; }
.game-loader .spinner { width: 34px; height: 34px; border: 4px solid var(--border); border-top-color: var(--accent); border-radius: 50%; animation: spin 0.8s linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }
.game-loader .gl-title { font-family: var(--font-display); font-weight: 700; font-size: 16px; }
.game-loader .gl-hint { font-size: 12px; color: var(--text-muted); max-width: 340px; text-align: center; }
.game-loader button { margin-top: 4px; padding: 6px 14px; border-radius: 999px; border: none; background: var(--accent); color: #fff; font-weight: 700; cursor: pointer; }

.browser-bar { display: flex; align-items: center; gap: 8px; margin-bottom: 12px; }
.browser-bar input { flex: 1; }
.proxy-frame { width: 100%; height: 65vh; border: none; border-radius: 14px; background: #000; }
.unavailable { border: 2px dashed var(--border); border-radius: 18px; padding: 40px; text-align: center; color: var(--text-muted); max-width: 500px; margin: 0 auto; }
.unavailable .material-symbols-rounded { font-size: 40px; color: var(--accent-bright); display: block; margin-bottom: 12px; }

.ai-layout { display: flex; gap: 20px; max-width: 1500px; margin: 0 auto; padding: 0 0 20px; height: calc(100vh - 260px); min-height: 420px; }
.chat-main { flex: 1 1 0; max-width: 1000px; margin: 0 auto; min-width: 0; display: flex; flex-direction: column; }
.ai-browser-pane { display: none; flex: 1 1 0; min-width: 340px; flex-direction: column; border: 2px solid var(--border); border-radius: 14px; overflow: hidden; background: var(--bg-elevated); }
.ai-browser-pane.open { display: flex; }
.ai-browser-bar { display: flex; align-items: center; justify-content: space-between; padding: 10px 14px; background: var(--bg-elevated); border-bottom: 2px solid var(--border); flex-shrink: 0; }
.ai-browser-title { font-family: var(--font-display); font-weight: 700; font-size: 14px; color: var(--text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 260px; }
.ai-browser-actions { display: flex; gap: 6px; }
.ai-browser-btn { display: flex; align-items: center; justify-content: center; width: 32px; height: 32px; border-radius: 50%; border: 2px solid var(--border); background: var(--bg-elevated); color: var(--icon-color); text-decoration: none; cursor: pointer; transition: background 0.2s ease, border-color 0.2s ease; }
.ai-browser-btn:hover { background: var(--bg-elevated-hover); border-color: var(--accent); }
.ai-browser-btn .material-symbols-rounded { font-size: 17px; }
.ai-browser-body { position: relative; flex: 1; }
.ai-browser-frame { position: absolute; inset: 0; width: 100%; height: 100%; border: none; display: block; background: #fff; }
.ai-browser-loader { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; background: var(--bg); transition: opacity 0.3s ease; z-index: 5; }
.ai-browser-loader.gone { opacity: 0; pointer-events: none; }
.chat-header-bar { display: flex; align-items: center; justify-content: space-between; padding: 0 0 14px; border-bottom: 1px solid var(--border); flex-shrink: 0; }
.chat-title { font-family: var(--font-display); font-weight: 700; font-size: 20px; color: var(--text); }
.chat-online { font-size: 13px; color: var(--text-muted); display: flex; align-items: center; gap: 6px; cursor: pointer; background: none; border: none; font-family: var(--font-body); padding: 6px 12px; border-radius: 999px; transition: background 0.15s, color 0.15s; }
.chat-online:hover { background: var(--bg-elevated-hover); color: var(--text); }
.chat-messages { flex: 1; overflow-y: auto; padding: 16px 0; display: flex; flex-direction: column; gap: 8px; scroll-behavior: smooth; }
.chat-messages::-webkit-scrollbar { width: 5px; }
.chat-messages::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }
.chat-msg { display: flex; flex-direction: column; gap: 2px; max-width: 100%; }
.chat-msg-meta { display: flex; align-items: baseline; gap: 8px; }
.chat-msg-name { font-family: var(--font-display); font-weight: 700; font-size: 13px; color: var(--accent-bright); }
.chat-msg.mine .chat-msg-name { color: var(--accent); }
.chat-msg-text { font-size: 14px; color: var(--text); line-height: 1.5; word-break: break-word; padding: 8px 12px; background: var(--bg-elevated); border: 1px solid var(--border); border-radius: 0 12px 12px 12px; display: inline-block; max-width: 92%; }
.chat-msg.mine { align-items: flex-end; }
.chat-msg.mine .chat-msg-meta { flex-direction: row-reverse; }
.chat-msg.mine .chat-msg-text { background: var(--accent-glow); border-color: var(--accent); border-radius: 12px 0 12px 12px; }
.chat-msg-text:not(.md) { white-space: pre-wrap; }
.chat-sys { font-size: 12px; color: var(--text-muted); text-align: center; padding: 4px 0; font-style: italic; }
.chat-msg-text.md > *:first-child { margin-top: 0; }
.chat-msg-text.md > *:last-child { margin-bottom: 0; }
.chat-msg-text.md h1, .chat-msg-text.md h2, .chat-msg-text.md h3 { font-family: var(--font-display); font-weight: 700; margin: 14px 0 6px; line-height: 1.3; }
.chat-msg-text.md h1 { font-size: 18px; }
.chat-msg-text.md h2 { font-size: 16px; }
.chat-msg-text.md h3 { font-size: 14.5px; }
.chat-msg-text.md p { margin: 8px 0; }
.chat-msg-text.md strong { color: var(--accent-bright); }
.chat-msg-text.md ul, .chat-msg-text.md ol { margin: 8px 0; padding-left: 22px; }
.chat-msg-text.md li { margin: 3px 0; }
.chat-msg-text.md hr { border: none; border-top: 1px solid var(--border); margin: 14px 0; }
.chat-msg-text.md code { background: var(--bg); border: 1px solid var(--border); border-radius: 4px; padding: 1px 5px; font-size: 13px; }
.chat-msg-text.md pre { background: var(--bg); border: 1px solid var(--border); border-radius: 8px; padding: 10px 12px; overflow-x: auto; margin: 8px 0; }
.chat-msg-text.md pre code { background: none; border: none; padding: 0; }
.chat-msg-text.md blockquote { border-left: 3px solid var(--accent); margin: 8px 0; padding: 2px 12px; color: var(--text-muted); }
.chat-msg-text.md table { border-collapse: collapse; margin: 8px 0; font-size: 13px; display: block; max-width: 100%; overflow-x: auto; white-space: nowrap; }
.chat-msg-text.md th, .chat-msg-text.md td { border: 1px solid var(--border); padding: 4px 8px; }
.chat-msg-text.md a { color: var(--accent-bright); }
.chat-msg-text.md .katex { font-size: 1.05em; }
.chat-msg-text.md .katex-display { margin: 10px 0; overflow-x: auto; overflow-y: hidden; }
#aiTypingLabel { color: var(--text-muted); font-size: 13px; font-style: italic; }
.ai-typing { display: inline-flex; gap: 4px; padding: 4px 2px; }
.ai-typing span { width: 6px; height: 6px; border-radius: 50%; background: var(--text-muted); animation: aiTypingBounce 1.2s infinite ease-in-out; }
.ai-typing span:nth-child(2) { animation-delay: 0.15s; }
.ai-typing span:nth-child(3) { animation-delay: 0.3s; }
@keyframes aiTypingBounce { 0%, 60%, 100% { transform: translateY(0); opacity: 0.5; } 30% { transform: translateY(-4px); opacity: 1; } }
.chat-input-area { flex-shrink: 0; padding: 14px 0 0; border-top: 1px solid var(--border); display: flex; flex-direction: column; gap: 10px; }
.chat-send-row { display: flex; gap: 8px; }
.chat-text-input { flex: 1; background: var(--bg-elevated); border: 2px solid var(--border); border-radius: 10px; color: var(--text); font-family: var(--font-body); font-size: 14px; padding: 10px 14px; outline: none; transition: border-color 0.15s, box-shadow 0.15s; }
.chat-text-input:focus { border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-glow); }
.chat-text-input::placeholder { color: var(--text-muted); }
.chat-send-btn { background: var(--accent); border: none; border-radius: 10px; color: var(--bg); font-family: var(--font-body); font-size: 14px; font-weight: 700; padding: 10px 20px; display: flex; align-items: center; gap: 6px; cursor: pointer; transition: background 0.15s; }
.chat-send-btn:hover { background: var(--accent-bright); }
.chat-send-btn:disabled { opacity: 0.5; cursor: default; }
</style>
</head>
<body>

