const THEME_KEY = "velcro_standalone_theme";
function applyTheme(t) {
 document.documentElement.setAttribute("data-theme", t);
 const icon = document.getElementById("themeToggle")?.querySelector(".material-symbols-rounded");
 if (icon) icon.textContent = t === "light" ? "dark_mode" : "light_mode";
}
applyTheme(localStorage.getItem(THEME_KEY) || "dark");
document.getElementById("themeToggle").addEventListener("click", () => {
 const next = document.documentElement.getAttribute("data-theme") === "light" ? "dark" : "light";
 localStorage.setItem(THEME_KEY, next);
 applyTheme(next);
});

function showView(name) {
 document.querySelectorAll(".view").forEach(v => v.classList.remove("active"));
 document.getElementById("view-" + name).classList.add("active");
 document.querySelectorAll(".site-nav a[data-view]").forEach(a => a.classList.toggle("active", a.dataset.view === name));
}
document.querySelectorAll(".site-nav a[data-view]").forEach(a => a.addEventListener("click", () => showView(a.dataset.view)));

function buildCard(item, launchFn) {
 const a = document.createElement("a");
 a.className = "game-card";
 a.href = "javascript:void(0)";
 const cover = document.createElement("span");
 cover.className = "cover";
 cover.style.backgroundImage = "url('" + item.thumbnail + "')";
 const info = document.createElement("span");
 info.className = "info";
 const name = document.createElement("span");
 name.className = "name";
 name.textContent = item.title;
 const cat = document.createElement("span");
 cat.className = "cat";
 cat.textContent = item.category || "";
 info.appendChild(name); info.appendChild(cat);
 a.appendChild(cover); a.appendChild(info);
 a.addEventListener("click", () => launchFn(item));
 return a;
}

const gamesGrid = document.getElementById("gamesGrid");
const gamesSearch = document.getElementById("gamesSearch");
document.getElementById("gameCount").textContent = GAMES.length + " games";
function renderGames() {
 const q = gamesSearch.value.trim().toLowerCase();
 gamesGrid.innerHTML = "";
 const frag = document.createDocumentFragment();
 GAMES.filter(g => !q || g.title.toLowerCase().includes(q)).slice(0, 200).forEach(g => {
 frag.appendChild(buildCard(g, item => launchGame(item.url.startsWith("/") ? location.origin + item.url : item.url, item.title)));
 });
 gamesGrid.appendChild(frag);
}
gamesSearch.addEventListener("input", renderGames);
renderGames();

const appsGrid = document.getElementById("appsGrid");
APPS.forEach(a => appsGrid.appendChild(buildCard(a, item => launchGame(item.url, item.title))));

