// --- proxy engine: libcurl.js (WASM HTTP client tunneled over WISP) ------
// Same engine as the full site (see public/libcurl-proxy.js there) inlined
// here since this is a single static file with no server of its own — no
// service worker anywhere, which is also what makes this file able to run
// unmodified inside Apps Script's HtmlService (which can't host one at all).
// See that file's comments for the full reasoning behind each piece below;
// the one thing that differs here is the cookie relay (nowgg.fun-style
// sites need real Set-Cookie access libcurl.js never exposes): the real
// site has its own Express route for that, this file instead calls back
// into Code.gs's cookieFetch() via google.script.run when running inside
// Apps Script, or the same /api/cookie-fetch route when just served
// statically somewhere that happens to have it (best-effort either way).
let proxyReady = false;
const WISP = "wss://anura.pro/wisp/";
let lcReadyPromise = null;
async function lcWaitForGlobal() {
 if (typeof libcurl !== "undefined" && libcurl) return;
 for (let i = 0; i < 100; i++) {
 if (typeof libcurl !== "undefined" && libcurl) return;
 await new Promise(r => setTimeout(r, 50));
 }
 throw new Error("libcurl.js global not found");
}
async function lcInit(statusEl) {
 if (lcReadyPromise) return lcReadyPromise;
 lcReadyPromise = (async () => {
 await lcWaitForGlobal();
 await new Promise((resolve, reject) => {
 const timeout = setTimeout(() => reject(new Error("libcurl.js init timed out")), 20000);
 libcurl.onload = () => { clearTimeout(timeout); resolve(); };
 libcurl.load_wasm("https://cdn.jsdelivr.net/npm/libcurl.js@0.7.1/libcurl.wasm");
 });
 libcurl.set_websocket(WISP);
 proxyReady = true;
 if (statusEl) statusEl.textContent = "proxy ready — using the public wss://anura.pro/wisp/ relay (this file has no server of its own)";
 })();
 lcReadyPromise.catch(err => { if (statusEl) statusEl.textContent = "proxy init failed: " + err.message; });
 return lcReadyPromise;
}

const LC_COOKIE_RELAY_HOSTS = [/(^|\.)nowgg\.fun$/i];
const lcCookieJar = new Map();
function lcNeedsCookieRelay(url) {
 let host;
 try { host = new URL(url).hostname; } catch { return false; }
 return LC_COOKIE_RELAY_HOSTS.some(re => re.test(host));
}
function lcCookieDomainKey(domain) { return domain.replace(/^\./, "").toLowerCase(); }
function lcStoreSetCookie(setCookieStr, requestHostname) {
 const parts = setCookieStr.split(";").map(s => s.trim());
 const nameValue = parts[0] || "";
 const eq = nameValue.indexOf("=");
 if (eq < 0) return;
 const name = nameValue.slice(0, eq).trim();
 const value = nameValue.slice(eq + 1).trim();
 let domain = requestHostname;
 for (const attr of parts.slice(1)) {
 const aEq = attr.indexOf("=");
 if (aEq < 0) continue;
 if (attr.slice(0, aEq).trim().toLowerCase() === "domain") domain = attr.slice(aEq + 1).trim();
 }
 const key = lcCookieDomainKey(domain);
 if (!lcCookieJar.has(key)) lcCookieJar.set(key, new Map());
 lcCookieJar.get(key).set(name, value);
}
function lcCookieHeaderFor(hostname) {
 const h = hostname.toLowerCase();
 const pairs = [];
 for (const [domain, map] of lcCookieJar) {
 if (h === domain || h.endsWith("." + domain)) {
 for (const [k, v] of map) pairs.push(`${k}=${v}`);
 }
 }
 return pairs.join("; ");
}
function lcBase64ToBytes(b64) {
 const bin = atob(b64 || "");
 const bytes = new Uint8Array(bin.length);
 for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
 return bytes;
}
function lcHasGAS() { return typeof google !== "undefined" && google.script && google.script.run; }
function lcRawCookieFetch(url, cookie, method, headers, body) {
 if (lcHasGAS()) {
 return new Promise((resolve, reject) => {
 google.script.run
 .withSuccessHandler(data => (data && data.error ? reject(new Error(data.error)) : resolve(data)))
 .withFailureHandler(err => reject(new Error((err && err.message) || String(err))))
 .cookieFetch(url, cookie, method, headers, body);
 });
 }
 return fetch("/api/cookie-fetch", {
 method: "POST",
 headers: { "content-type": "application/json" },
 body: JSON.stringify({ url, cookie, method, headers, body }),
 }).then(async r => {
 const data = await r.json();
 if (!r.ok) throw new Error(data.error || "cookie-fetch failed");
 return data;
 });
}
async function lcCookieRelayFetch(url, params = {}) {
 const hostname = new URL(url).hostname;
 const cookie = lcCookieHeaderFor(hostname);
 const data = await lcRawCookieFetch(url, cookie, params.method || "GET", params.headers || {}, typeof params.body === "string" ? params.body : undefined);
