 } catch (e) { return null; }
}
function lcRewriteJs(code) {
 return code
 .replace(/\b(?:window|self|document|top|parent)\.location\b/g, "window.__plocation")
 .replace(/(?<![.\w$])location\b(?!\s*:)/g, "window.__plocation");
