function lcShouldRewriteScript(el) {
 const type = (el.getAttribute("type") || "").toLowerCase();
 if (!type) return true;
 return type === "text/javascript" || type === "module" || type === "application/javascript";
}
async function lcFetchScriptBlobUrl(absUrl) {
 try {
 const res = await lcDoFetch(absUrl);
