}
async function lcRewriteAndLoad(iframeEl, url, onStatus) {
 onStatus && onStatus("fetching " + url);
 const res = await lcDoFetch(url);
 const finalUrl = res.url || url;
 const html = await res.text();
 const doc = new DOMParser().parseFromString(html, "text/html");
 if (!doc.querySelector("base")) {
 const base = doc.createElement("base");
 base.href = finalUrl;
 doc.head?.prepend(base);
 }
 doc.querySelectorAll("script:not([src])").forEach(el => {
 if (lcShouldRewriteScript(el) && el.textContent) el.textContent = lcRewriteJs(el.textContent);
 });
 const INLINE_EVENT_ATTRS = /^on\w+$/;
 doc.querySelectorAll("*").forEach(el => {
 for (const attr of Array.from(el.attributes)) {
 if (INLINE_EVENT_ATTRS.test(attr.name) && attr.value) el.setAttribute(attr.name, lcRewriteJs(attr.value));
 }
 });
 const assets = [];
 doc.querySelectorAll("link[rel=stylesheet][href], script[src], img[src]").forEach(el => {
 const attr = el.tagName === "LINK" ? "href" : "src";
 const raw = el.getAttribute(attr);
 if (!raw || raw.startsWith("data:") || raw.startsWith("blob:")) return;
 let abs;
 try { abs = new URL(raw, finalUrl).href; } catch { return; }
 const isScript = el.tagName === "SCRIPT" && lcShouldRewriteScript(el);
 assets.push({ el, attr, abs, isScript });
 });
 onStatus && onStatus("loading " + assets.length + " sub-resources");
 await Promise.all(assets.map(async a => {
 const blobUrl = a.isScript ? await lcFetchScriptBlobUrl(a.abs) : await lcFetchAsBlobUrl(a.abs);
 if (blobUrl) a.el.setAttribute(a.attr, blobUrl);
 else a.el.removeAttribute(a.attr);
 }));
 const bootstrapScript = doc.createElement("script");
 bootstrapScript.textContent = lcBuildBootstrap(finalUrl);
 doc.head?.prepend(bootstrapScript);
 iframeEl.srcdoc = "<!DOCTYPE html>\n" + doc.documentElement.outerHTML;
 onStatus && onStatus("loaded " + finalUrl);
 return finalUrl;
}
async function lcNavigate(iframeEl, url, onStatus, onNavigated) {
 await lcInit();
 if (onNavigated) iframeEl.__libcurlOnNavigated = onNavigated;
 if (!iframeEl.hasAttribute("sandbox")) {
 iframeEl.setAttribute("sandbox", "allow-scripts allow-forms allow-same-origin allow-popups");
 }
 if (!iframeEl.__libcurlNavHandler) {
 iframeEl.__libcurlNavHandler = (e) => {
 if (e.source !== iframeEl.contentWindow) return;
 const fetchReq = e.data && e.data.__libcurlProxyFetchRequest;
 if (fetchReq) { lcHandleRuntimeFetch(iframeEl, fetchReq); return; }
 const target = e.data && e.data.__libcurlProxyNavigate;
 if (!target) return;
 lcRewriteAndLoad(iframeEl, target, onStatus)
 .then(finalUrl => iframeEl.__libcurlOnNavigated && iframeEl.__libcurlOnNavigated(finalUrl))
 .catch(err => onStatus && onStatus("error: " + err.message));
 };
 window.addEventListener("message", iframeEl.__libcurlNavHandler);
 }
 return lcRewriteAndLoad(iframeEl, url, onStatus);
}
lcInit(document.getElementById("proxyStatus"));

// --- browser tab (address-bar browsing, separate from the game player) ---
const proxyFrame = document.getElementById("proxyFrame");
const urlBar = document.getElementById("urlBar");
function resolveUrl(input) {
 const t = input.trim();
 if (!t) return null;
 if (/^https?:\/\//i.test(t)) return t;
 if (t.includes(".") && !t.includes(" ")) return "https://" + t;
 return "https://duckduckgo.com/?q=" + encodeURIComponent(t);
}
function browserNavigate(url) {
 urlBar.value = url;
 const isLocal = url.startsWith(location.origin + "/") || url.startsWith("/");
 if (isLocal) { proxyFrame.removeAttribute("srcdoc"); proxyFrame.src = url; return; }
 lcNavigate(proxyFrame, url, msg => { document.getElementById("proxyStatus").textContent = msg; })
 .catch(err => { document.getElementById("proxyStatus").textContent = "failed: " + err.message; });
}
document.getElementById("goBtn").addEventListener("click", () => { const u = resolveUrl(urlBar.value); if (u) browserNavigate(u); });
urlBar.addEventListener("keydown", e => { if (e.key === "Enter") { const u = resolveUrl(urlBar.value); if (u) browserNavigate(u); } });

// --- game player (dedicated fullscreen overlay, matching game.html) ---
const gamePlayer = document.getElementById("gamePlayer");
const gameFrame = document.getElementById("gameFrame");
const gameLoader = document.getElementById("gameLoader");
const glDismiss = document.getElementById("glDismiss");
let loaderHidden = false, loaderTimer = null, dismissTimer = null;

function hideLoader() {
 if (loaderHidden) return;
 loaderHidden = true;
 gameLoader.classList.add("gone");
 clearTimeout(loaderTimer); clearTimeout(dismissTimer);
}
glDismiss.addEventListener("click", hideLoader);

function closePlayer() {
 gamePlayer.classList.remove("open");
 document.body.classList.remove("player-open");
 gameFrame.removeAttribute("srcdoc");
 gameFrame.src = "about:blank";
}
document.getElementById("playerBack").addEventListener("click", closePlayer);
document.getElementById("playerClose").addEventListener("click", closePlayer);

async function launchGame(url, title) {
 gamePlayer.classList.add("open");
 document.body.classList.add("player-open");
 document.getElementById("gameTitle").textContent = title;
 document.getElementById("glTitle").textContent = title;
 loaderHidden = false;
 gameLoader.classList.remove("gone");
 glDismiss.hidden = true;
 loaderTimer = setTimeout(hideLoader, 45000);
 dismissTimer = setTimeout(() => { if (!loaderHidden) glDismiss.hidden = false; }, 8000);

 const isLocal = url.startsWith(location.origin + "/") || url.startsWith("/");
 if (isLocal) { gameFrame.removeAttribute("srcdoc"); gameFrame.src = url; return; }
 try {
 await lcNavigate(gameFrame, url, msg => { document.getElementById("glHint").textContent = msg; });
 setTimeout(hideLoader, 250);
 } catch (err) {
 document.getElementById("glHint").textContent = "failed: " + err.message;
 }
}

// --- ai chat -------------------------------------------------------------
// Same feature as the real site's ai.html/ai.js, adapted for here: the
// browser panel reuses our own lcNavigate() (srcdoc + libcurl.js) instead
// of scramjet, and the chat request itself goes through google.script.run
// (Apps Script) or /api/ai/chat (if this file happens to be served by a
// real backend that has it) instead of a streaming fetch — see lcRawCookieFetch
// above for the same dual-path pattern. google.script.run can't stream, so
// the whole tool-calling loop runs server-side in one blocking call and
// the reply + any queued browser actions land together at the end.
(function () {
 const messagesEl = document.getElementById("chatMessages");
 const input = document.getElementById("chatTextInput");
 const sendBtn = document.getElementById("chatSendBtn");
 const newChatBtn = document.getElementById("aiNewChat");
 const browserPane = document.getElementById("aiBrowserPane");
 const browserFrame = document.getElementById("aiBrowserFrame");
 const browserLoader = document.getElementById("aiBrowserLoader");
 const browserTitle = document.getElementById("aiBrowserTitle");
 const browserClose = document.getElementById("aiBrowserClose");
 const browserOpenTab = document.getElementById("aiBrowserOpenTab");
 let currentBrowserUrl = "";

 function closeAiBrowser() {
 browserPane.classList.remove("open");
 browserFrame.removeAttribute("srcdoc");
 browserFrame.src = "about:blank";
 currentBrowserUrl = "";
 }
 browserClose.addEventListener("click", closeAiBrowser);
 browserOpenTab.addEventListener("click", () => { if (currentBrowserUrl) window.open(currentBrowserUrl, "_blank", "noopener"); });

 async function openInAiBrowser(action) {
 browserPane.classList.add("open");
 browserLoader.classList.remove("gone");
 if (action.isDataHtml && typeof action.html === "string") {
 currentBrowserUrl = "";
 browserTitle.textContent = action.title || "code preview";
 browserFrame.removeAttribute("sandbox");
 browserFrame.srcdoc = action.html;
 browserLoader.classList.add("gone");
 return;
 }
 const url = action.url;
 currentBrowserUrl = url;
 browserTitle.textContent = action.title || url;
 const isLocal = url.startsWith(location.origin + "/") || url.startsWith("/");
 if (isLocal) { browserFrame.removeAttribute("srcdoc"); browserFrame.src = url; browserLoader.classList.add("gone"); return; }
 try {
 await lcNavigate(browserFrame, url, () => {});
 } catch (e) {}
 browserLoader.classList.add("gone");
 }

 function scrollAiBrowser(direction, amount) {
 try {
 const win = browserFrame.contentWindow;
 win.scrollBy({ top: direction === "up" ? -(amount || 600) : (amount || 600), behavior: "smooth" });
 } catch (e) {}
 }

 function clickAiBrowser(text) {
 try {
 const doc = browserFrame.contentDocument;
 if (!doc) return;
 const lower = String(text || "").trim().toLowerCase();
 const candidates = doc.querySelectorAll("a,button,input[type=submit],input[type=button],[role=button],summary");
 for (const el of candidates) {
 const t = (el.innerText || el.value || el.getAttribute("aria-label") || "").trim().toLowerCase();
 if (t && t.includes(lower)) { el.click(); return; }
 }
 } catch (e) {}
 }

 function goBackAiBrowser() {
 try { browserFrame.contentWindow.history.back(); } catch (e) {}
 }

 async function applyAiAction(action) {
 if (action.type === "open_url") await openInAiBrowser(action);
 else if (action.type === "scroll_browser") scrollAiBrowser(action.direction, action.amount);
 else if (action.type === "click_browser") clickAiBrowser(action.text);
 else if (action.type === "go_back_browser") goBackAiBrowser();
 else if (action.type === "close_browser") closeAiBrowser();
 }

 function getAiPageContext() {
 if (!browserPane.classList.contains("open") || !currentBrowserUrl) return null;
 try {
 const doc = browserFrame.contentDocument;
 const text = doc?.body?.innerText;
 if (!text) return null;
 return { url: currentBrowserUrl, text: text.slice(0, 4000) };
 } catch (e) { return null; }
 }

 function rawAiChat(messagesJson, pageContextJson) {
 if (lcHasGAS()) {
 return new Promise((resolve, reject) => {
 google.script.run
 .withSuccessHandler(data => (data && data.error ? reject(new Error(data.error)) : resolve(data)))
 .withFailureHandler(err => reject(new Error((err && err.message) || String(err))))
 .aiChat(messagesJson, pageContextJson);
 });
 }
 return fetch("/api/ai/chat", {
 method: "POST",
 headers: { "content-type": "application/json" },
 body: JSON.stringify({ messages: JSON.parse(messagesJson), pageContext: pageContextJson ? JSON.parse(pageContextJson) : null }),
 }).then(async r => {
 if (!r.ok || !r.body) {
 let msg = "request failed";
 try { msg = (await r.json())?.error || msg; } catch (e) {}
 throw new Error(msg);
 }
 // the real backend streams NDJSON status/final events; here we just
 // want the final one, so drain the stream and keep only that.
 const reader = r.body.getReader();
 const decoder = new TextDecoder();
 let buffer = "", final = null;
 while (true) {
 const { done, value } = await reader.read();
 if (done) break;
 buffer += decoder.decode(value, { stream: true });
 let idx;
 while ((idx = buffer.indexOf("\n")) !== -1) {
 const line = buffer.slice(0, idx);
 buffer = buffer.slice(idx + 1);
 if (!line.trim()) continue;
 const evt = JSON.parse(line);
 if (evt.type === "final") final = evt;
 else if (evt.type === "error") throw new Error(evt.error);
 }
 }
 if (!final) throw new Error("no response from ai");
 return { reply: final.reply, actions: final.actions };
 });
 }

 const AI_STORAGE_KEY = "velcro_ai_history";
 let aiHistory = [];
 try {
 const saved = JSON.parse(localStorage.getItem(AI_STORAGE_KEY) || "[]");
 if (Array.isArray(saved)) aiHistory = saved;
 } catch (e) {}
 function saveAiHistory() { try { localStorage.setItem(AI_STORAGE_KEY, JSON.stringify(aiHistory)); } catch (e) {} }
 function scrollAiToEnd() { messagesEl.scrollTop = messagesEl.scrollHeight; }

 function renderAiMarkdown(text) {
 const mathBlocks = [];
 const protectedText = text.replace(/\\\[[\s\S]*?\\\]|\\\([\s\S]*?\\\)|\$\$[\s\S]*?\$\$|\$[^\n$]+?\$/g, m => { mathBlocks.push(m); return `@@MATH${mathBlocks.length - 1}@@`; });
 let html = marked.parse(protectedText, { breaks: true });
 html = html.replace(/@@MATH(\d+)@@/g, (_, i) => mathBlocks[+i]);
 return DOMPurify.sanitize(html);
 }

 function renderAiMessage(role, text, rich) {
 const wrap = document.createElement("div");
 wrap.className = "chat-msg" + (role === "user" ? " mine" : "");
 const meta = document.createElement("div");
 meta.className = "chat-msg-meta";
 const name = document.createElement("span");
 name.className = "chat-msg-name";
 name.textContent = role === "user" ? "you" : "ai";
 meta.appendChild(name);
 const bubble = document.createElement("div");
 bubble.className = "chat-msg-text";
 if (rich && window.marked && window.DOMPurify) {
 bubble.classList.add("md");
 bubble.innerHTML = renderAiMarkdown(text);
 if (window.renderMathInElement) {
 renderMathInElement(bubble, {
 delimiters: [
 { left: "$$", right: "$$", display: true },
 { left: "\\[", right: "\\]", display: true },
 { left: "\\(", right: "\\)", display: false },
 { left: "$", right: "$", display: false },
 ],
 throwOnError: false,
 });
 }
 } else {
 bubble.textContent = text;
 }
 wrap.appendChild(meta);
 wrap.appendChild(bubble);
 messagesEl.appendChild(wrap);
 scrollAiToEnd();
 return bubble;
 }

 function renderAiTyping() {
 const wrap = document.createElement("div");
 wrap.className = "chat-msg";
 wrap.id = "aiTypingMsg";
 const bubble = document.createElement("div");
 bubble.className = "chat-msg-text";
 bubble.innerHTML = '<span class="ai-typing"><span></span><span></span><span></span></span>';
 wrap.appendChild(bubble);
 messagesEl.appendChild(wrap);
 scrollAiToEnd();
 }
 function removeAiTyping() { document.getElementById("aiTypingMsg")?.remove(); }

 function renderAiHistory() {
 messagesEl.innerHTML = "";
 if (aiHistory.length === 0) {
 const sys = document.createElement("div");
 sys.className = "chat-sys";
 sys.textContent = "ask anything — this is one continuous conversation until you start a new chat";
 messagesEl.appendChild(sys);
 return;
 }
 for (const m of aiHistory) renderAiMessage(m.role, m.content, m.role === "assistant");
 }

 async function sendAiMessage() {
 const text = input.value.trim();
 if (!text || sendBtn.disabled) return;
 input.value = "";
 aiHistory.push({ role: "user", content: text });
 saveAiHistory();
 renderAiMessage("user", text);
 sendBtn.disabled = true;
 input.disabled = true;
 renderAiTyping();
 try {
 const pageContext = getAiPageContext();
 const result = await rawAiChat(JSON.stringify(aiHistory), pageContext ? JSON.stringify(pageContext) : null);
 removeAiTyping();
 aiHistory.push({ role: "assistant", content: result.reply || "" });
 saveAiHistory();
 renderAiMessage("assistant", result.reply || "", true);
 for (const action of result.actions || []) {
 await applyAiAction(action);
 await new Promise(r => setTimeout(r, 350));
 }
 } catch (err) {
 removeAiTyping();
 renderAiMessage("assistant", "something went wrong talking to the ai: " + (err?.message || err));
 } finally {
 sendBtn.disabled = false;
 input.disabled = false;
 input.focus();
 }
 }

 sendBtn.addEventListener("click", sendAiMessage);
 input.addEventListener("keydown", e => { if (e.key === "Enter") sendAiMessage(); });
 newChatBtn.addEventListener("click", () => { aiHistory = []; saveAiHistory(); renderAiHistory(); });
 renderAiHistory();
})();
</script>
</body>
</html>
"; document.open(); document.write(html); document.close(); })();
